mapper.select:
SELECT o.account_id AS accountId, o.marketing_task_id AS marketingTaskId, mt.task_name AS taskName, mt.task_end_at AS taskEndAt, o.occupied_at AS occupiedAt FROM marketing_account_occupancy o JOIN marketing_task mt ON mt.id = o.marketing_task_id AND mt.deleted_at IS NULL AND mt.status IN (1, 2, 5) WHERE o.account_id IN
#{accountId}
ORDER BY o.account_id ASC
